import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1795170900000}'),i={name:"zh-CN/guide/faq.md"};function l(s,a,h,n,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>关于 Persim 的快速解答。</p><h3 id="persim-收费吗" tabindex="-1">Persim 收费吗？ <a class="header-anchor" href="#persim-收费吗" aria-label="Permalink to &quot;Persim 收费吗？&quot;">​</a></h3><p>可以从 Mac App Store 免费下载，基础浏览功能可直接使用。部分高级能力通过应用内购买解锁，免费版会在标签栏显示一个小标记。</p><h3 id="支持哪些系统" tabindex="-1">支持哪些系统？ <a class="header-anchor" href="#支持哪些系统" aria-label="Permalink to &quot;支持哪些系统？&quot;">​</a></h3><p>Persim 面向 macOS 12 及以上，兼容 Apple Silicon 与 Intel 芯片的 Mac。</p><h3 id="我的数据会上传吗" tabindex="-1">我的数据会上传吗？ <a class="header-anchor" href="#我的数据会上传吗" aria-label="Permalink to &quot;我的数据会上传吗？&quot;">​</a></h3><p>不需要账户。历史、书签、会话和下载记录都留在你的 Mac 上。需要联网的功能（例如更新广告拦截订阅）只获取它需要的内容；Cookie 管理器里可以清除站点数据。</p><h3 id="怎么导入其他浏览器的书签" tabindex="-1">怎么导入其他浏览器的书签？ <a class="header-anchor" href="#怎么导入其他浏览器的书签" aria-label="Permalink to &quot;怎么导入其他浏览器的书签？&quot;">​</a></h3><p>在 Chrome 或 Edge 中把书签导出为 HTML 文件，再在 Persim 书签管理器里选择「导入 HTML」。多层文件夹和重复链接都会自动处理。</p><h3 id="怎么保存网页上的视频" tabindex="-1">怎么保存网页上的视频？ <a class="header-anchor" href="#怎么保存网页上的视频" aria-label="Permalink to &quot;怎么保存网页上的视频？&quot;">​</a></h3><p>打开嗅探面板，选择识别到的视频并下载。分成多段的视频会合成一个 MP4，下载完可以用你平时用的应用打开。</p><h3 id="怎么切换界面语言" tabindex="-1">怎么切换界面语言？ <a class="header-anchor" href="#怎么切换界面语言" aria-label="Permalink to &quot;怎么切换界面语言？&quot;">​</a></h3><p>打开 <code>persim://settings</code> → 「常规」→「界面语言」。应用提供 25 种语言，重新打开窗口后生效。</p><h3 id="还有其他问题" tabindex="-1">还有其他问题？ <a class="header-anchor" href="#还有其他问题" aria-label="Permalink to &quot;还有其他问题？&quot;">​</a></h3><p>写信到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>，告诉我们你想做什么，我们会尽力帮忙。</p>',16)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
